def compute(vars):
    thereafter_maturities = vars["v1"]
    total_recourse_debt = vars["v2"]
    if total_recourse_debt == 0:
        return None

    ratio = thereafter_maturities / total_recourse_debt
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "thereafter_maturities": thereafter_maturities,
            "total_recourse_debt": total_recourse_debt,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
